window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8bab78663a483113"]={"versions": [{"id": "FIG-8bab78663a483113", "releases": ["R1.3.0", "R17-10_R1.2.0", "R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm visualisiert das Protokoll- und Nachrichtenlayout für die „DTR Data Status Message Structure“ innerhalb des AUTOSAR Remote Event Communication Protocols (RECM). Es ordnet die logische PDU- bzw. Frame-Struktur einer Punkt-zu-Punkt-Kommunikation zwischen einer Quell-ECU („Source Section ECU“) und einer Ziel-ECU („Destination Section ECU“) zu. Gezeigt wird die Abfolge von Header-, Payload- und Trailer-Elementen einschließlich mehrdimensionaler/strukturierter Datenelemente in Blockdarstellung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten sind die sendende „Source Section ECU“ und die empfangende „Destination Section ECU“. Der Nachrichtenaufbau gliedert sich in folgende sequenzielle Felder:</p>\n<ul class=\"fig-list\"><li>Header-Felder (flache Blöcke):\n<ul class=\"fig-list\"><li><code>MSG_TYPE</code>: Nachrichtentyp zur Identifikation der Nachricht als DTR Data Status Message (<code>RECM_MSG_STAT_DTR_DATA</code>).\n</li><li><code>CLIENT_ID</code>: Kennung des anfordernden bzw. zugeordneten Clients.\n</li><li><code>RESERVED</code>: Reserviertes Protokollfeld.\n</li></ul>\n</li><li>Payload-Felder (vertiefte/längliche Blöcke zur Symbolisierung strukturierter Datensätze):\n<ul class=\"fig-list\"><li><code>STATUS_1</code>, <code>STATUS_2</code> bis <code>STATUS_X</code>: Eindimensionales Array variabler Länge (<code>NUM_ELEM</code> Statusstrukturen) von DTR Data Status Information Elementen (<code>STRCT_DTR_DATA_STAT</code>), die jeweils Identifikatoren und zugeordnete Statusinformationen kapseln.\n</li></ul>\n</li><li>Trailer-Feld:\n<ul class=\"fig-list\"><li><code>MSG_CTR</code>: Nachrichtenzähler (Message Counter) zur Sequenz- und Übertragungsüberwachung.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die „Source Section ECU“ generiert die DTR Data Status Message und initiiert die Übertragung zur „Destination Section ECU“ (angedeutet durch den ausgehenden Pfeil an der Quell-ECU und den eingehenden Pfeil an der Ziel-ECU). Der Übertragungsstrom setzt sich aus der Serialisierung der Metadaten (<code>MSG_TYPE</code>, <code>CLIENT_ID</code>, <code>RESERVED</code>), gefolgt von einer dynamischen Anzahl von Statusblöcken (<code>STATUS_1</code> bis <code>STATUS_X</code>) und dem abschließenden Überwachungszähler (<code>MSG_CTR</code>) zusammen. Die Ziel-ECU deserialisiert die Felder zur weiteren Diagnose- und Ereignisverarbeitung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Strukturierung definiert die normative PDU-Serialisierungsreihenfolge für DTR-Statusnachrichten gemäß PRS_RECM_00095 und PRS_RECM_00096. Entwickler müssen sicherstellen, dass die Anzahl der übertragenen Statuselemente (<code>STATUS_1</code> bis <code>STATUS_X</code>) strikt mit dem vorangehenden bzw. zugehörigen Elementzähler (<code>NUM_ELEM</code>) korrespondiert und jedes Element dem Datentyp <code>STRCT_DTR_DATA_STAT</code> entspricht. Der abschließende <code>MSG_CTR</code> erfordert eine korrekte Inkrementierung auf Senderseite und Validierung auf Empfängerseite zur Erkennung von Paketverlusten oder Fehlübertragungen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2233eb4cfc21e03e", "releases": ["R17-03_R1.1.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm visualisiert das Protokoll- und Nachrichtenlayout für die „DTR Data Status Message Structure“ innerhalb des AUTOSAR Remote Event Communication Protocols (RECM). Es ordnet die logische PDU- bzw. Frame-Struktur einer Punkt-zu-Punkt-Kommunikation zwischen einer Quell-ECU („Source Section ECU“) und einer Ziel-ECU („Destination Section ECU“) zu. Gezeigt wird die Abfolge von Header-, Payload- und Trailer-Elementen einschließlich mehrdimensionaler/strukturierter Datenelemente in Blockdarstellung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten sind die sendende „Source Section ECU“ und die empfangende „Destination Section ECU“. Der Nachrichtenaufbau gliedert sich in folgende sequenzielle Felder:</p>\n<ul class=\"fig-list\"><li>Header-Felder (flache Blöcke):\n<ul class=\"fig-list\"><li><code>MSG_TYPE</code>: Nachrichtentyp zur Identifikation der Nachricht als DTR Data Status Message (<code>RECM_MSG_STAT_DTR_DATA</code>).\n</li><li><code>CLIENT_ID</code>: Kennung des anfordernden bzw. zugeordneten Clients.\n</li><li><code>RESERVED</code>: Reserviertes Protokollfeld.\n</li></ul>\n</li><li>Payload-Felder (vertiefte/längliche Blöcke zur Symbolisierung strukturierter Datensätze):\n<ul class=\"fig-list\"><li><code>STATUS_1</code>, <code>STATUS_2</code> bis <code>STATUS_X</code>: Eindimensionales Array variabler Länge (<code>NUM_ELEM</code> Statusstrukturen) von DTR Data Status Information Elementen (<code>STRCT_DTR_DATA_STAT</code>), die jeweils Identifikatoren und zugeordnete Statusinformationen kapseln.\n</li></ul>\n</li><li>Trailer-Feld:\n<ul class=\"fig-list\"><li><code>MSG_CTR</code>: Nachrichtenzähler (Message Counter) zur Sequenz- und Übertragungsüberwachung.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die „Source Section ECU“ generiert die DTR Data Status Message und initiiert die Übertragung zur „Destination Section ECU“ (angedeutet durch den ausgehenden Pfeil an der Quell-ECU und den eingehenden Pfeil an der Ziel-ECU). Der Übertragungsstrom setzt sich aus der Serialisierung der Metadaten (<code>MSG_TYPE</code>, <code>CLIENT_ID</code>, <code>RESERVED</code>), gefolgt von einer dynamischen Anzahl von Statusblöcken (<code>STATUS_1</code> bis <code>STATUS_X</code>) und dem abschließenden Überwachungszähler (<code>MSG_CTR</code>) zusammen. Die Ziel-ECU deserialisiert die Felder zur weiteren Diagnose- und Ereignisverarbeitung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Strukturierung definiert die normative PDU-Serialisierungsreihenfolge für DTR-Statusnachrichten gemäß PRS_RECM_00095 und PRS_RECM_00096. Entwickler müssen sicherstellen, dass die Anzahl der übertragenen Statuselemente (<code>STATUS_1</code> bis <code>STATUS_X</code>) strikt mit dem vorangehenden bzw. zugehörigen Elementzähler (<code>NUM_ELEM</code>) korrespondiert und jedes Element dem Datentyp <code>STRCT_DTR_DATA_STAT</code> entspricht. Der abschließende <code>MSG_CTR</code> erfordert eine korrekte Inkrementierung auf Senderseite und Validierung auf Empfängerseite zur Erkennung von Paketverlusten oder Fehlübertragungen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-8bab78663a483113", "to": "FIG-2233eb4cfc21e03e", "fr": "R1.3.0", "tr": "R17-03_R1.1.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-2233eb4cfc21e03e", "to": "FIG-8bab78663a483113", "fr": "R17-03_R1.1.0", "tr": "R17-10_R1.2.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
